ben: Go: add simple retry loop and io.EOF handling. keep it reader-friendly.

harin: Go example (compact):
```go
ctx := context.Background()
var cursor string = ""
for a := 0; a < 3; a++ {
  stream, err := client.GenerateStream(ctx, &GenerateOptions{Prompt: prompt, Cursor: cursor})
  if err != nil {
    time.Sleep(time.Duration(100*(1<<a)) * time.Millisecond)
    continue
  }
  for {
    tok, err := stream.Recv()
    if err == io.EOF { break }
    if err != nil { /* retry on transient */ break }
    fmt.Print(tok)
  }
  break
}
```

